from datetime import datetime
def filter_log_events(log_lines: list, start_time: str, end_time: str) -> list:
    date_fmt = '%Y-%m-%d %H:%M:%S'
    try:
        start_dt = datetime.strptime(start_time, date_fmt)
        end_dt = datetime.strptime(end_time, date_fmt)
    except ValueError:
        return []
    result = []
    for line in log_lines:
        if len(line) < 19:
            continue
        ts_str = line[:19]
        try:
            ts_dt = datetime.strptime(ts_str, date_fmt)
            if start_dt <= ts_dt <= end_dt:
                result.append(line)
        except ValueError:
            continue
    return result
